from pathlib import Path
import re,sys
root=Path(sys.argv[1] if len(sys.argv)>1 else '_site')
p=root/'index.html'
s=p.read_text('utf-8')

def rep(old,new,label):
    global s
    if old not in s:
        raise SystemExit(f'missing patch target: {label}')
    s=s.replace(old,new,1)

s=re.sub(r'\n\s*<div id="teacherDashboard" class="cloud-wall cloud-hidden">.*?<div id="teacherTable" class="teacher-table"></div></div>', '', s, count=1, flags=re.S)

