start=s.index('  async function initCloud(){')
end=s.index('\n\n    migrateLegacy();',start)
new_init=r'''  async function initCloud(){refreshCloudUI();if(!cloudClient)return;let {data}=await cloudClient.auth.getSession();let sess=data?.session;if(!sess)return;cloudState.user=sess.user;const recovery=new URLSearchParams(location.search).get('teacher_recovery')==='1',email=String(sess.user?.email||'').toLowerCase();let role=sess.user.user_metadata?.role||'';cloudState.role=email===FIXED_TEACHER_EMAIL?'teacher':(role==='student'?'student':'');if(cloudState.role==='teacher'){if(recovery){go('account',{bypass:true})}else{await loadTeacherClasses();go('teacher',{bypass:true});teacherSwitchTab('publish')}}else if(cloudState.role==='student'){let {data:m}=await cloudClient.from('class_members').select('class_id,student_code,classes(name,join_code)').eq('user_id',sess.user.id).eq('role','student').maybeSingle();if(m){cloudState.classId=m.class_id;cloudState.className=m.classes?.name||'';let cls=m.classes?.join_code||localStorage.getItem('ratiobot_last_class')||'',sid=m.student_code||localStorage.getItem('ratiobot_last_student')||'';let {data:pr}=await cloudClient.from('profiles').select('display_name').eq('user_id',sess.user.id).maybeSingle();let {data:acct}=await cloudClient.from('student_accounts').select('login_name,must_change_password').eq('user_id',sess.user.id).maybeSingle();cloudState.displayName=pr?.display_name||sid;cloudState.username=acct?.login_name||`${cls}-${sid}`;cloudState.mustChangePassword=!!acct?.must_change_password;$('#accountClassInput').value=cls;$('#accountStudentInput').value=sid;await cloudLoadStudentData(cls,sid);if(cloudState.mustChangePassword){$('#firstPasswordBox').classList.remove('cloud-hidden');go('account',{bypass:true})}}}refreshCloudUI()}'''
s=s[:start]+new_init+s[end:]

s=s.replace('教师账号固定，不开放注册。登录后先创建班级，并设置一个学生容易输入的“班级用户名”；学生随后即可自行注册。','教师账号固定，不开放注册。登录成功后会进入独立“教师控制台”，发布学生名册、查看数据并管理账号。',1)
for bad in ["$('#bulkCreateStudentsBtn').onclick","$('#copyCredentialsBtn').onclick"]:
    if bad in s: raise SystemExit('stale runtime binding remains: '+bad)
p.write_text(s,'utf-8')
print('teacher console patch applied')
